using Microsoft.EntityFrameworkCore;
using VaxStock.DataAccess.Entities;
namespace VaxStock.DataAccess.Data;
public sealed class WarehouseDbContext(DbContextOptions<WarehouseDbContext> options) : DbContext(options)
{
    public DbSet<AppUser> AppUserRecords => Set<AppUser>();
    public DbSet<Warehouse> WarehouseRecords => Set<Warehouse>();
    public DbSet<WarehouseAssignment> WarehouseAssignmentRecords => Set<WarehouseAssignment>();
    public DbSet<Organization> OrganizationRecords => Set<Organization>();
    public DbSet<Vaccine> VaccineRecords => Set<Vaccine>();
    public DbSet<VaccineBatch> VaccineBatchRecords => Set<VaccineBatch>();
    public DbSet<Receipt> ReceiptRecords => Set<Receipt>();
    public DbSet<ReceiptDetail> ReceiptDetailRecords => Set<ReceiptDetail>();
    public DbSet<StockSegment> StockSegmentRecords => Set<StockSegment>();
    public DbSet<Issue> IssueRecords => Set<Issue>();
    public DbSet<IssueDetail> IssueDetailRecords => Set<IssueDetail>();
    public DbSet<StockReservation> StockReservationRecords => Set<StockReservation>();
    public DbSet<StockMovement> StockMovementRecords => Set<StockMovement>();
    public DbSet<QualityDecision> QualityDecisionRecords => Set<QualityDecision>();
    public DbSet<TradeShipment> TradeShipmentRecords => Set<TradeShipment>();
    public DbSet<ShipmentDocumentLink> ShipmentDocumentLinkRecords => Set<ShipmentDocumentLink>();
    public DbSet<AuditLog> AuditLogRecords => Set<AuditLog>();
    public DbSet<Incident> IncidentRecords => Set<Incident>();
    public DbSet<IncidentStockSegment> IncidentStockSegmentRecords => Set<IncidentStockSegment>();
    public DbSet<StockDisposition> StockDispositionRecords => Set<StockDisposition>();
    public DbSet<StockDispositionDetail> StockDispositionDetailRecords => Set<StockDispositionDetail>();
    protected override void OnModelCreating(ModelBuilder b)
    {
        b.Entity<AppUser>().Property(x => x.AuthVersion).HasDefaultValue(0);
        b.Entity<AppUser>().Property(x => x.RowVersion).IsRowVersion();
        b.Entity<WarehouseAssignment>().Property(x => x.RowVersion).IsRowVersion();
        b.Entity<Warehouse>().Property(x => x.RowVersion).IsRowVersion();
        b.Entity<Organization>().Property(x => x.RowVersion).IsRowVersion();
        b.Entity<Vaccine>().Property(x => x.RowVersion).IsRowVersion();
        b.Entity<VaccineBatch>().Property(x => x.RowVersion).IsRowVersion();
        b.Entity<Organization>().ToTable(t => t.HasCheckConstraint("CK_Organization_Kind", "[Kind] IN ('Manufacturer','Supplier','Recipient','Carrier')"));
        b.Entity<AppUser>().Property(x => x.Username).HasMaxLength(200).IsRequired();
        b.Entity<AppUser>().Property(x => x.PasswordHash).HasMaxLength(200).IsRequired();
        b.Entity<AppUser>().Property(x => x.FullName).HasMaxLength(200).IsRequired();
        b.Entity<AppUser>().Property(x => x.Role).HasMaxLength(200).IsRequired();
        b.Entity<Warehouse>().Property(x => x.Code).HasMaxLength(200).IsRequired();
        b.Entity<Warehouse>().Property(x => x.Name).HasMaxLength(200).IsRequired();
        b.Entity<Organization>().Property(x => x.Code).HasMaxLength(200).IsRequired();
        b.Entity<Organization>().Property(x => x.Name).HasMaxLength(200).IsRequired();
        b.Entity<Organization>().Property(x => x.Country).HasMaxLength(200).IsRequired();
        b.Entity<Organization>().Property(x => x.Kind).HasMaxLength(200).IsRequired();
        b.Entity<Vaccine>().Property(x => x.Code).HasMaxLength(200).IsRequired();
        b.Entity<Vaccine>().Property(x => x.Name).HasMaxLength(200).IsRequired();
        b.Entity<Vaccine>().Property(x => x.StorageMin).HasPrecision(18, 2);
        b.Entity<Vaccine>().Property(x => x.StorageMax).HasPrecision(18, 2);
        b.Entity<VaccineBatch>().Property(x => x.BatchNo).HasMaxLength(200).IsRequired();
        b.Entity<Receipt>().Property(x => x.DocumentNo).HasMaxLength(200).IsRequired();
        b.Entity<Receipt>().Property(x => x.Status).HasMaxLength(200).IsRequired();
        b.Entity<ReceiptDetail>().Property(x => x.UnitPrice).HasPrecision(18, 2);
        b.Entity<StockSegment>().Property(x => x.QualityStatus).HasMaxLength(200).IsRequired();
        b.Entity<Issue>().Property(x => x.DocumentNo).HasMaxLength(200).IsRequired();
        b.Entity<Issue>().Property(x => x.Status).HasMaxLength(200).IsRequired();
        b.Entity<IssueDetail>().Property(x => x.UnitPrice).HasPrecision(18, 2);
        b.Entity<QualityDecision>().Property(x => x.Status).HasMaxLength(200).IsRequired();
        b.Entity<QualityDecision>().Property(x => x.Reason).HasMaxLength(2000).IsRequired();
        b.Entity<TradeShipment>().Property(x => x.Code).HasMaxLength(200).IsRequired();
        b.Entity<TradeShipment>().Property(x => x.Kind).HasMaxLength(200).IsRequired();
        b.Entity<TradeShipment>().Property(x => x.OriginCountry).HasMaxLength(200).IsRequired();
        b.Entity<TradeShipment>().Property(x => x.DestinationCountry).HasMaxLength(200).IsRequired();
        b.Entity<TradeShipment>().Property(x => x.Status).HasMaxLength(200).IsRequired();
        b.Entity<AuditLog>().Property(x => x.Action).HasMaxLength(200).IsRequired();
        b.Entity<AuditLog>().Property(x => x.EntityType).HasMaxLength(200).IsRequired();
        // Full JSON audit reasons may exceed 2000 after escaping; never truncate them.
        b.Entity<AuditLog>().Property(x => x.Details).HasColumnType("nvarchar(max)").IsRequired();
        b.Entity<WarehouseAssignment>().HasOne<AppUser>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<WarehouseAssignment>().HasOne<Warehouse>().WithMany().HasForeignKey(x => x.WarehouseId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<Vaccine>().HasOne<Organization>().WithMany().HasForeignKey(x => x.ManufacturerId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<VaccineBatch>().HasOne<Vaccine>().WithMany().HasForeignKey(x => x.VaccineId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<Receipt>().HasOne<Warehouse>().WithMany().HasForeignKey(x => x.WarehouseId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<Receipt>().HasOne<Organization>().WithMany().HasForeignKey(x => x.SupplierId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<Receipt>().HasOne<AppUser>().WithMany().HasForeignKey(x => x.CreatedById).OnDelete(DeleteBehavior.Restrict);
        b.Entity<ReceiptDetail>().HasOne<Receipt>().WithMany().HasForeignKey(x => x.ReceiptId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<ReceiptDetail>().HasOne<VaccineBatch>().WithMany().HasForeignKey(x => x.BatchId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockSegment>().HasOne<ReceiptDetail>().WithMany().HasForeignKey(x => x.ReceiptDetailId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockSegment>().HasOne<Warehouse>().WithMany().HasForeignKey(x => x.WarehouseId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<Issue>().HasOne<Warehouse>().WithMany().HasForeignKey(x => x.WarehouseId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<Issue>().HasOne<Organization>().WithMany().HasForeignKey(x => x.RecipientId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<Issue>().HasOne<AppUser>().WithMany().HasForeignKey(x => x.CreatedById).OnDelete(DeleteBehavior.Restrict);
        b.Entity<IssueDetail>().HasOne<Issue>().WithMany().HasForeignKey(x => x.IssueId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<IssueDetail>().HasOne<StockSegment>().WithMany().HasForeignKey(x => x.StockSegmentId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockReservation>().HasOne<IssueDetail>().WithMany().HasForeignKey(x => x.IssueDetailId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockMovement>().HasOne<StockSegment>().WithMany().HasForeignKey(x => x.StockSegmentId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockMovement>().HasOne<ReceiptDetail>().WithMany().HasForeignKey(x => x.ReceiptDetailId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockMovement>().HasOne<IssueDetail>().WithMany().HasForeignKey(x => x.IssueDetailId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<QualityDecision>().HasOne<StockSegment>().WithMany().HasForeignKey(x => x.StockSegmentId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<QualityDecision>().HasOne<AppUser>().WithMany().HasForeignKey(x => x.DecidedById).OnDelete(DeleteBehavior.Restrict);
        b.Entity<TradeShipment>().HasOne<Organization>().WithMany().HasForeignKey(x => x.PartnerId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<ShipmentDocumentLink>().HasOne<TradeShipment>().WithMany().HasForeignKey(x => x.TradeShipmentId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<ShipmentDocumentLink>().HasOne<Receipt>().WithMany().HasForeignKey(x => x.ReceiptId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<ShipmentDocumentLink>().HasOne<Issue>().WithMany().HasForeignKey(x => x.IssueId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<AuditLog>().HasOne<AppUser>().WithMany().HasForeignKey(x => x.ActorId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<AppUser>().HasIndex(x => x.Username).IsUnique();
        b.Entity<Warehouse>().HasIndex(x => x.Code).IsUnique();
        b.Entity<Organization>().HasIndex(x => x.Code).IsUnique();
        b.Entity<Vaccine>().HasIndex(x => x.Code).IsUnique();
        b.Entity<Receipt>().HasIndex(x => x.DocumentNo).IsUnique();
        b.Entity<Issue>().HasIndex(x => x.DocumentNo).IsUnique();
        b.Entity<TradeShipment>().HasIndex(x => x.Code).IsUnique();
        b.Entity<StockSegment>().HasIndex(x => x.ReceiptDetailId).IsUnique();
        b.Entity<StockReservation>().HasIndex(x => x.IssueDetailId).IsUnique();
        b.Entity<WarehouseAssignment>().HasIndex(x => new { x.UserId, x.WarehouseId }).IsUnique();
        b.Entity<VaccineBatch>().HasIndex(x => new { x.VaccineId, x.BatchNo }).IsUnique();
        b.Entity<StockSegment>().Property(x => x.RowVersion).IsRowVersion();
        b.Entity<StockMovement>().HasIndex(x => x.ReceiptDetailId).IsUnique().HasFilter("[ReceiptDetailId] IS NOT NULL");
        b.Entity<StockMovement>().HasIndex(x => x.IssueDetailId).IsUnique().HasFilter("[IssueDetailId] IS NOT NULL");
        b.Entity<AppUser>().ToTable(t => t.HasCheckConstraint("CK_AppUser_Valid", "[Role] IN ('Admin','WarehouseStaff','QualityManager')"));
        b.Entity<Vaccine>().ToTable(t => t.HasCheckConstraint("CK_Vaccine_Valid", "[DosesPerVial] > 0 AND [VialsPerPack] > 0 AND [StorageMin] < [StorageMax]"));
        b.Entity<VaccineBatch>().ToTable(t => t.HasCheckConstraint("CK_VaccineBatch_Valid", "[ManufacturedAt] IS NULL OR [ManufacturedAt] <= [ExpiresAt]"));
        b.Entity<ReceiptDetail>().ToTable(t => t.HasCheckConstraint("CK_ReceiptDetail_Valid", "[Quantity] > 0 AND [UnitPrice] >= 0"));
        b.Entity<IssueDetail>().ToTable(t => t.HasCheckConstraint("CK_IssueDetail_Valid", "[Quantity] > 0 AND [UnitPrice] >= 0"));
        b.Entity<StockReservation>().ToTable(t => t.HasCheckConstraint("CK_StockReservation_Valid", "[Quantity] > 0"));
        b.Entity<StockSegment>().ToTable(t => t.HasCheckConstraint("CK_StockSegment_Valid", "[QualityStatus] IN ('Pending','Released','Quarantined','Rejected')"));
        b.Entity<QualityDecision>().ToTable(t => t.HasCheckConstraint("CK_QualityDecision_Valid", "[Status] IN ('Pending','Released','Quarantined','Rejected')"));
        b.Entity<Receipt>().ToTable(t => t.HasCheckConstraint("CK_Receipt_Valid", "([Status] = 'Draft' AND [PostedAt] IS NULL) OR ([Status] = 'Posted' AND [PostedAt] IS NOT NULL)"));
        b.Entity<Issue>().ToTable(t => t.HasCheckConstraint("CK_Issue_Valid", "([Status] IN ('Draft','Cancelled') AND [PostedAt] IS NULL) OR ([Status] = 'Posted' AND [PostedAt] IS NOT NULL)"));
        b.Entity<StockMovement>().ToTable(t => t.HasCheckConstraint("CK_StockMovement_Valid", "([ReceiptDetailId] IS NOT NULL AND [IssueDetailId] IS NULL AND [StockDispositionDetailId] IS NULL AND [QuantityDelta] > 0) OR ([ReceiptDetailId] IS NULL AND [IssueDetailId] IS NOT NULL AND [StockDispositionDetailId] IS NULL AND [QuantityDelta] < 0) OR ([ReceiptDetailId] IS NULL AND [IssueDetailId] IS NULL AND [StockDispositionDetailId] IS NOT NULL AND [QuantityDelta] < 0)"));
        b.Entity<ShipmentDocumentLink>().ToTable(t => t.HasCheckConstraint("CK_ShipmentDocumentLink_Valid", "([ReceiptId] IS NOT NULL AND [IssueId] IS NULL) OR ([ReceiptId] IS NULL AND [IssueId] IS NOT NULL)"));

        b.Entity<Incident>().Property(x => x.Code).HasMaxLength(200).IsRequired();
        b.Entity<Incident>().Property(x => x.Kind).HasMaxLength(200).IsRequired();
        b.Entity<Incident>().Property(x => x.Description).HasMaxLength(2000).IsRequired();
        b.Entity<Incident>().Property(x => x.Status).HasMaxLength(200).IsRequired();
        b.Entity<Incident>().Property(x => x.Resolution).HasMaxLength(2000);
        b.Entity<Incident>().Property(x => x.RowVersion).IsRowVersion();
        b.Entity<Incident>().HasIndex(x => x.Code).IsUnique();
        b.Entity<Incident>().HasIndex(x => new { x.WarehouseId, x.Status });
        b.Entity<Incident>().HasOne<Warehouse>().WithMany().HasForeignKey(x => x.WarehouseId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<Incident>().HasOne<AppUser>().WithMany().HasForeignKey(x => x.ReportedById).OnDelete(DeleteBehavior.Restrict);
        b.Entity<Incident>().HasOne<AppUser>().WithMany().HasForeignKey(x => x.ClosedById).OnDelete(DeleteBehavior.Restrict);
        b.Entity<Incident>().ToTable(t =>
        {
            t.HasCheckConstraint("CK_Incident_Valid", "([Status] IN ('Open','Investigating') AND [ClosedAt] IS NULL AND [ClosedById] IS NULL AND [Resolution] IS NULL) OR ([Status] = 'Closed' AND [ClosedAt] IS NOT NULL AND [ClosedById] IS NOT NULL AND [Resolution] IS NOT NULL AND LEN(LTRIM(RTRIM([Resolution]))) > 0)");
            t.HasCheckConstraint("CK_Incident_Dates", "[ReportedAt] >= [OccurredAt] AND ([ClosedAt] IS NULL OR [ClosedAt] >= [ReportedAt])");
            t.HasCheckConstraint("CK_Incident_Kind", "[Kind] IN ('TemperatureExcursion','PackagingDamage','Expiry','Recall','Other')");
        });
        b.Entity<IncidentStockSegment>().Property(x => x.ReleaseReason).HasMaxLength(2000);
        b.Entity<IncidentStockSegment>().HasIndex(x => new { x.IncidentId, x.StockSegmentId }).IsUnique();
        b.Entity<IncidentStockSegment>().HasIndex(x => new { x.StockSegmentId, x.ReleasedAt });
        b.Entity<IncidentStockSegment>().HasOne<Incident>().WithMany().HasForeignKey(x => x.IncidentId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<IncidentStockSegment>().HasOne<StockSegment>().WithMany().HasForeignKey(x => x.StockSegmentId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<IncidentStockSegment>().HasOne<AppUser>().WithMany().HasForeignKey(x => x.ReleasedById).OnDelete(DeleteBehavior.Restrict);
        b.Entity<IncidentStockSegment>().ToTable(t => t.HasCheckConstraint("CK_IncidentStockSegment_Valid", "([ReleasedAt] IS NULL AND [ReleasedById] IS NULL AND [ReleaseReason] IS NULL) OR ([ReleasedAt] IS NOT NULL AND [ReleasedAt] >= [BlockedAt] AND [ReleasedById] IS NOT NULL AND [ReleaseReason] IS NOT NULL AND LEN(LTRIM(RTRIM([ReleaseReason]))) > 0)"));

        b.Entity<QualityDecision>().HasOne<Incident>().WithMany().HasForeignKey(x => x.IncidentId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockDisposition>().Property(x => x.DocumentNo).HasMaxLength(200).IsRequired();
        b.Entity<StockDisposition>().Property(x => x.Kind).HasMaxLength(200).IsRequired();
        b.Entity<StockDisposition>().Property(x => x.Status).HasMaxLength(200).IsRequired();
        b.Entity<StockDisposition>().Property(x => x.Reason).HasMaxLength(2000).IsRequired();
        b.Entity<StockDisposition>().Property(x => x.RowVersion).IsRowVersion();
        b.Entity<StockDisposition>().HasIndex(x => x.DocumentNo).IsUnique();
        b.Entity<StockDisposition>().HasOne<Warehouse>().WithMany().HasForeignKey(x => x.WarehouseId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockDisposition>().HasOne<Organization>().WithMany().HasForeignKey(x => x.SupplierId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockDisposition>().HasOne<Incident>().WithMany().HasForeignKey(x => x.IncidentId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockDisposition>().HasOne<AppUser>().WithMany().HasForeignKey(x => x.CreatedById).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockDisposition>().HasOne<AppUser>().WithMany().HasForeignKey(x => x.ApprovedById).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockDisposition>().ToTable(t =>
        {
            t.HasCheckConstraint("CK_StockDisposition_Valid", "([Status] IN ('Draft','Cancelled') AND [ApprovedAt] IS NULL AND [ApprovedById] IS NULL AND [PostedAt] IS NULL) OR ([Status] = 'Approved' AND [ApprovedAt] IS NOT NULL AND [ApprovedById] IS NOT NULL AND [PostedAt] IS NULL) OR ([Status] = 'Posted' AND [ApprovedAt] IS NOT NULL AND [ApprovedById] IS NOT NULL AND [PostedAt] IS NOT NULL AND [PostedAt] >= [ApprovedAt])");
            t.HasCheckConstraint("CK_StockDisposition_Kind", "([Kind] = 'ReturnToSupplier' AND [SupplierId] IS NOT NULL) OR ([Kind] = 'Destroy' AND [SupplierId] IS NULL)");
            t.HasCheckConstraint("CK_StockDisposition_Reason", "LEN(LTRIM(RTRIM([Reason]))) > 0");
        });
        b.Entity<StockDispositionDetail>().HasOne<StockDisposition>().WithMany().HasForeignKey(x => x.StockDispositionId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockDispositionDetail>().HasOne<StockSegment>().WithMany().HasForeignKey(x => x.StockSegmentId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockDispositionDetail>().HasIndex(x => new { x.StockDispositionId, x.StockSegmentId }).IsUnique();
        b.Entity<StockDispositionDetail>().ToTable(t => t.HasCheckConstraint("CK_StockDispositionDetail_Valid", "[Quantity] > 0"));
        b.Entity<StockMovement>().HasOne<StockDispositionDetail>().WithMany().HasForeignKey(x => x.StockDispositionDetailId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<StockMovement>().HasIndex(x => x.StockDispositionDetailId).IsUnique().HasFilter("[StockDispositionDetailId] IS NOT NULL");
        b.Entity<VaccineBatch>().HasIndex(x => x.ExpiresAt);
        b.Entity<StockSegment>().HasIndex(x => new { x.WarehouseId, x.QualityStatus });
    }
}
